  automation: ['autoreply', 'Automation & AI', 'Use the established Mistral settings, auto-reply rules, AI test, logs and guardrails.'],
  'hot-leads': ['hot-leads', 'Hot leads', 'Review keyword and sentiment-driven sales opportunities.'],
  templates: ['templates', 'Templates & Spintax', 'Manage existing message templates and campaign text variants.'],
  blacklist: ['shield-ban', 'Blacklist manager', 'Protect campaigns and replies from blocked recipients.'],
  unified: ['unified', 'Email campaigns', 'Create, review, test and schedule Brevo-first email campaigns.'],
  'email-contacts': ['email-contacts', 'Email contacts', 'Import, organise and maintain subscribed, unsubscribed, bounced and suppressed email audiences.'],
  sendpulse: ['sendpulse', 'Email providers', 'Configure Brevo primary delivery and the SendPulse fallback queue.'],
  'ab-tests': ['ab-tests', 'A/B tests', 'Run the established test, split and reporting workflows.'],
