function getSharedTemplates(){
  try{
    let templates=JSON.parse(localStorage.getItem('sv_wa_templates')||'[]');
    if(!Array.isArray(templates) || templates.length === 0){
      templates = DEFAULT_SVRIAS_TEMPLATES;
      localStorage.setItem('sv_wa_templates', JSON.stringify(templates));
    }
    return templates.map(t=>({id:t.id,name:cleanTemplateText(t.name)||'Untitled template',body:cleanTemplateText(t.body||t.message||t.text||'')}));
  }catch{
    return DEFAULT_SVRIAS_TEMPLATES.map(t=>({id:t.id,name:cleanTemplateText(t.name),body:cleanTemplateText(t.body)}));
  }
}

async function syncWhatsAppTemplates(){
  try{
    const res = await api('/api/whatsapp/templates');
    if(res && Array.isArray(res.templates) && res.templates.length > 0){
      localStorage.setItem('sv_wa_templates', JSON.stringify(res.templates));
      loadTemplateSelectors();
      return res.templates;
    }
  }catch(e){
    console.warn('Could not sync WhatsApp templates from backend:', e.message);
  }
  return getSharedTemplates();
}

function sampleSpintax(value){let result=String(value||'');for(let pass=0;pass<10;pass++){const next=result.replace(/\{([^{}|]+(?:\|[^{}]+)+)\}/g,(_,choices)=>{const options=choices.split('|').map(option=>option.trim()).filter(Boolean);return options.length?options[Math.floor(Math.random()*options.length)]:'';});if(next===result)break;result=next;}return result;}
function templateSampleMarkup(template){const source=template.body||'',sample=sampleSpintax(source);return `<div class="spintax-preview quick-template-sample"><b>Sample variation</b><span>${escapeHtml(sample)}</span><details><summary>View editable Spintax source</summary><pre>${escapeHtml(source)}</pre></details></div>`;}
function loadTemplateSelectors(){const templates=getSharedTemplates();for(const cfg of [{select:'#quickTemplate',preview:'#quickTemplatePreview',target:'#quickText'},{select:'#campaignTemplate',preview:'#campaignTemplatePreview',target:'#campaignText'}]){const select=$(cfg.select);if(!select)continue;select.innerHTML='<option value="">Custom message</option>'+templates.map((t,i)=>`<option value="${i}">${escapeHtml(t.name)}</option>`).join('');select.onchange=()=>{const template=templates[Number(select.value)];const preview=$(cfg.preview);if(!template){preview.textContent='Select a template to preview and insert it.';return}preview.innerHTML=templateSampleMarkup(template);$(cfg.target).value=template.body;};}}
async function ensureCampaignSafeguardsUi(){if($('#campaignAudienceBuilder'))return;const preview=$('#campaignPreview'),delivery=$('#campaignDelay')?.closest('.inline-fields'),actions=$('#campaignAttachments')?.nextElementSibling;if(!preview||!delivery||!actions)return;preview.insertAdjacentHTML('afterend','<section id="campaignAudienceBuilder" class="audience-builder"><div class="section-head"><div><h3>CRM audience</h3><p>Build a targeted list from your contact records.</p></div><button type="button" class="secondary-btn small" data-action="build-campaign-audience"><i data-lucide="filter"></i> Build audience</button></div><div class="inline-fields audience-fields"><label>Tag<select id="campaignSegmentTag"><option value="">Any tag</option></select></label><label>Lead stage<select id="campaignSegmentStage"><option value="">Any stage</option></select></label><label>Country<select id="campaignSegmentCountry"><option value="">Any country</option></select></label></div><label class="checkbox-row"><input id="campaignRequireOptIn" type="checkbox"> Only contacts with recorded opt-in</label></section>');delivery.insertAdjacentHTML('afterend','<details class="campaign-safeguards"><summary>Delivery safeguards</summary><div class="inline-fields audience-fields"><label>Quiet hours start<input id="campaignQuietStart" type="time" value="21:00"></label><label>Quiet hours end<input id="campaignQuietEnd" type="time" value="08:00"></label><label>Daily sending limit<input id="campaignDailyLimit" type="number" min="0" value="0"><small>0 means no campaign cap.</small></label><label>Recent-send window (days)<input id="campaignDuplicateDays" type="number" min="0" max="365" value="30"></label></div><label class="checkbox-row"><input id="campaignSkipRecent" type="checkbox" checked> Skip people messaged within this window</label></details>');const launch=actions.querySelector('[data-action="launch-campaign"]');if(launch)launch.innerHTML='<i data-lucide="rocket"></i> Review & queue';launch?.insertAdjacentHTML('beforebegin','<button class="secondary-btn" data-action="campaign-preflight"><i data-lucide="clipboard-check"></i> Review campaign</button>');await populateCampaignSegments();iconRefresh();}
async function populateCampaignSegments(){if(!Object.keys(state.contacts||{}).length){try{const data=await api('/api/contacts');state.contacts=data.contacts||{};}catch{return;}}const contacts=Object.values(state.contacts||{}),unique=(values)=>[...new Set(values.filter(Boolean).map(value=>String(value).trim()))].sort((a,b)=>a.localeCompare(b));const put=(selector,values,label)=>{const node=$(selector);if(node)node.innerHTML=`<option value="">Any ${label}</option>`+values.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');};put('#campaignSegmentTag',unique(contacts.flatMap(contact=>Array.isArray(contact.tags)?contact.tags:[])),'tag');put('#campaignSegmentStage',unique(contacts.map(contact=>contact.leadStatus||'New')),'stage');put('#campaignSegmentCountry',unique(contacts.map(contact=>contact.country)),'country');}
function buildCampaignAudience(){const tag=$('#campaignSegmentTag')?.value||'',stage=$('#campaignSegmentStage')?.value||'',country=$('#campaignSegmentCountry')?.value||'',requireOptIn=Boolean($('#campaignRequireOptIn')?.checked);const selected=Object.values(state.contacts||{}).filter(contact=>{const tags=Array.isArray(contact.tags)?contact.tags:[];const optedIn=contact.optIn===true||contact.optedIn===true||String(contact.optInStatus||'').toLowerCase()==='opted_in';return(!tag||tags.includes(tag))&&(!stage||(contact.leadStatus||'New')===stage)&&(!country||contact.country===country)&&(!requireOptIn||optedIn);}).map(contact=>({jid:contact.jid,phone:String(contact.jid||'').split('@')[0],name:contact.name||''}));state.campaignContacts=selected;$('#campaignPreview').textContent=`${selected.length} CRM contacts selected${requireOptIn?' with recorded opt-in':''}. Run Review campaign before queuing.`;toast(`${selected.length} contacts added to campaign audience`,'success');}
function campaignPayload(){const quietStart=$('#campaignQuietStart')?.value||'',quietEnd=$('#campaignQuietEnd')?.value||'',order=$('#campaignOrder').value;return {name:$('#campaignName').value.trim(),contacts:state.campaignContacts,messageTemplate:$('#campaignText').value.trim(),attachments:state.campaignAttachments,mediaOrder:order==='text-first'?'text_first':order==='attachment-first'?'caption':'media_first',pollQuestion:state.campaignPoll?.question||'',pollOptions:state.campaignPoll?.options||[],scheduledFor:$('#campaignSchedule').value?new Date($('#campaignSchedule').value).getTime():Date.now(),delayBetweenMs:Math.max(3000,Number($('#campaignDelay')?.value||8)*1000),dripFollowups:state.dripSteps||[],requireOptIn:Boolean($('#campaignRequireOptIn')?.checked),skipRecentRecipients:Boolean($('#campaignSkipRecent')?.checked),duplicateWindowDays:Math.min(365,Math.max(0,Number($('#campaignDuplicateDays')?.value||30))),dailyLimit:Math.max(0,Number($('#campaignDailyLimit')?.value||0)),quietHours:quietStart&&quietEnd?{start:quietStart,end:quietEnd}:null};}
function campaignDuration(seconds){if(seconds<60)return `${Math.ceil(seconds)} seconds`;return `${Math.floor(seconds/60)} min ${Math.ceil(seconds%60)} sec`;}
async function reviewCampaign(shouldQueue=false){const payload=campaignPayload();if(!payload.name||!payload.contacts.length||(!payload.messageTemplate&&!payload.attachments.length&&!payload.pollQuestion))return toast('Add a name, contacts and campaign content','error');try{const report=await api('/api/campaigns/preflight',{method:'POST',body:JSON.stringify(payload)});const c=report.counts||{},warnings=[];if(c.unverified)warnings.push(`${c.unverified} not WhatsApp-verified yet`);if(c.recentlyMessaged)warnings.push(`${c.recentlyMessaged} contacted within the selected recent-send window`);if(c.blacklisted)warnings.push(`${c.blacklisted} blacklisted`);if(c.invalid)warnings.push(`${c.invalid} invalid number`);if(c.noRecordedOptIn)warnings.push(`${c.noRecordedOptIn} without recorded opt-in`);const quiet=payload.quietHours?`${payload.quietHours.start}–${payload.quietHours.end}`:'Off';showDialog(`<div class="dialog-content campaign-review"><p class="eyebrow">Campaign preflight</p><h2>${escapeHtml(payload.name)}</h2><div class="preflight-metrics"><div><b>${c.eligible||0}</b><span>eligible</span></div><div><b>${campaignDuration(report.estimatedSeconds||0)}</b><span>estimated duration</span></div><div><b>${payload.dailyLimit||'No cap'}</b><span>daily limit</span></div></div><div class="review-list"><p><b>Quiet hours:</b> ${escapeHtml(quiet)}</p><p><b>Delivery gap:</b> ${Math.round(payload.delayBetweenMs/1000)} seconds</p>${warnings.length?`<p class="review-warning"><b>Warnings:</b> ${escapeHtml(warnings.join(' · '))}</p>`:'<p class="review-ok">No blocking safety issues found.</p>'}</div><p class="muted">Only eligible recipients will be queued. Blacklisted, invalid, and opt-in-excluded contacts are never sent.</p><div class="dialog-actions"><button class="secondary-btn" value="cancel">Close</button>${shouldQueue&&c.eligible?'<button id="confirmCampaignQueue" class="primary-btn" value="default">Queue '+c.eligible+' recipients</button>':''}</div></div>`);if(shouldQueue&&c.eligible)$('#confirmCampaignQueue').addEventListener('click',async event=>{event.preventDefault();const button=$('#confirmCampaignQueue');button.disabled=true;button.textContent='Queueing…';try{await api('/api/campaigns',{method:'POST',body:JSON.stringify({...payload,contacts:report.eligibleContacts})});$('#crmDialog').close();clearCampaignDraft();loadCampaignQueue();toast('Campaign queued. You can create the next one now.','success')}catch(error){button.disabled=false;button.textContent='Queue campaign';toast(error.message,'error')}});}catch(error){toast(error.message,'error')}}
function clearCampaignDraft(){ $('#campaignName').value='';$('#campaignText').value='';$('#campaignSchedule').value='';$('#campaignPreview').textContent='Upload a CSV with phone and name columns.';state.campaignContacts=[];state.campaignAttachments=[];state.campaignPoll=null;state.dripSteps=[];renderAttachmentChips('campaign');renderDripSteps();}
function renderDripSteps(){const root=$('#dripSteps');if(!root)return;state.dripSteps=state.dripSteps||[];root.innerHTML=state.dripSteps.map((step,index)=>`<div class="drip-step"><label>Days after previous<input data-drip-days="${index}" type="number" min="1" value="${Number(step.daysAfter||1)}"></label><label>Message<textarea data-drip-message="${index}" rows="2">${escapeHtml(step.message||'')}</textarea></label><button class="text-btn" data-remove-drip="${index}">Remove</button></div>`).join('')||'<p class="muted">No follow-ups added. The campaign ends after its first message.</p>';}
async function verifyCampaignContacts(){if(!state.campaignContacts.length)return toast('Load contacts first','error');try{const phones=state.campaignContacts.map(c=>String(c.phone||c.jid||'').replace(/\D/g,''));const d=await api('/api/validate-numbers',{method:'POST',body:JSON.stringify({phones})});const invalid=new Set((d.invalid||[]).map(x=>String(x).replace(/\D/g,'')));state.campaignContacts=state.campaignContacts.map(c=>({...c,valid:!invalid.has(String(c.phone||c.jid||'').replace(/\D/g,''))}));$('#campaignPreview').textContent=`${state.campaignContacts.length-invalid.size} valid; ${invalid.size} invalid. Invalid contacts will be skipped.`;toast('Validation complete','success')}catch(e){toast(e.message,'error')}}
function openPoll(kind){showDialog(`<div class="dialog-content"><h2>Create WhatsApp poll</h2><p>Polls are sent last after any message or attachment.</p><label>Question<input id="pollQuestion" required placeholder="Your question"></label><label>Options — one per line<textarea id="pollOptions" rows="4" placeholder="Option 1&#10;Option 2"></textarea></label><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button class="primary-btn" id="savePoll" value="default">Save poll</button></div></div>`); $('#savePoll').addEventListener('click',e=>{e.preventDefault();const q=$('#pollQuestion').value.trim(),opts=$('#pollOptions').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!q||opts.length<2)return toast('Enter a question and at least two options','error');if(kind==='chat')sendPoll(q,opts);else{state[kind==='campaign'?'campaignPoll':'quickPoll']={question:q,options:opts};toast('Poll added','success');$('#crmDialog').close()} }); }
async function sendPoll(question, options){try{await api(`/api/inbox/${encodeURIComponent(state.activeJid)}/poll`,{method:'POST',body:JSON.stringify({question,options,selectableCount:1})});$('#crmDialog').close();await openChat(state.activeJid,false);toast('Poll sent','success')}catch(e){toast(e.message,'error')}}
async function toggleHandoff(){if(!state.activeJid)return;try{const escalated=$('#handoffBanner').hidden;const result=await api(`/api/inbox/${encodeURIComponent(state.activeJid)}/escalate`,{method:'POST',body:JSON.stringify({escalated})});await openChat(state.activeJid,false);toast(escalated?'Human takeover enabled':(result.message||'Chat AI enabled — it will answer only new inbound messages.'),'success')}catch(e){toast(e.message,'error')}}
function showDialog(html){$('#dialogContent').innerHTML=html; $('#crmDialog').showModal();iconRefresh();}
async function messageAction(action,id){if(!id||!state.activeJid)return;try{if(action==='edit'){const item=state.activeThread.find(m=>(m.id||m.messageId)===id);showDialog(`<div class="dialog-content"><h2>Edit CRM message</h2><p>This updates the stored CRM copy. Evolution support for remote edits depends on the connected instance.</p><label>Message<textarea id="editMessageText" rows="5">${escapeHtml(item?.text||'')}</textarea></label><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="saveEdit" class="primary-btn" value="default">Save</button></div></div>`);$('#saveEdit').addEventListener('click',async e=>{e.preventDefault();try{await api(`/api/inbox/${encodeURIComponent(state.activeJid)}/message/${encodeURIComponent(id)}`,{method:'PUT',body:JSON.stringify({text:$('#editMessageText').value})});$('#crmDialog').close();await openChat(state.activeJid,false);toast('Message updated','success')}catch(err){toast(err.message,'error')}});return;}const url=`/api/inbox/${encodeURIComponent(state.activeJid)}/message/${encodeURIComponent(id)}/${action==='everyone'?'everyone':'me'}`;await api(url,{method:'DELETE'});await openChat(state.activeJid,false);toast(action==='everyone'?'Delete request sent':'Message removed','success')}catch(e){toast(e.message,'error')}}

async function loadContacts(){try{const data=await api('/api/contacts');state.contacts=data.contacts||{};renderContacts();}catch(e){$('#contactsTable').innerHTML=`<tr><td colspan="6">${escapeHtml(e.message)}</td></tr>`}}
function renderContacts(){const term=$('#contactSearch').value.trim().toLowerCase();const records=Object.values(state.contacts).filter(c=>!term||`${c.name||''} ${c.jid||''}`.toLowerCase().includes(term));$('#contactsTable').innerHTML=records.map(c=>`<tr><td><div class="contact-cell">${avatarMarkup(c.name,c.profilePictureUrl)}<div><b>${escapeHtml(c.name||'Unknown')}</b><small>${escapeHtml(c.email||'')}</small></div></div></td><td>${escapeHtml((c.jid||'').replace(/@s\.whatsapp\.net$/,''))}</td><td>${escapeHtml(c.leadStatus||'New')}</td><td>${(c.tags||[]).slice(0,2).map(x=>`<span class="tag">${escapeHtml(x)}</span>`).join(' ')||'—'}</td><td>${formatTime(c.lastReceivedAt||c.statusUpdatedAt)}</td><td><button class="text-btn" data-open-contact="${escapeHtml(c.jid)}">Open</button></td></tr>`).join('')||'<tr><td colspan="6">No contacts found.</td></tr>';iconRefresh()}
function addContact(){showDialog(`<div class="dialog-content"><h2>Add CRM contact</h2><label>Name<input id="contactName" placeholder="Full name"></label><label>WhatsApp number<input id="contactPhone" placeholder="919876543210"></label><label>Tags, separated by commas<input id="contactTags" placeholder="Conference, Lead"></label><label class="checkbox-row"><input id="contactOptIn" type="checkbox"> Recorded marketing opt-in</label><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="saveContact" class="primary-btn" value="default">Add contact</button></div></div>`);$('#saveContact').addEventListener('click',async e=>{e.preventDefault();try{await api('/api/contacts/add',{method:'POST',body:JSON.stringify({name:$('#contactName').value.trim(),phone:$('#contactPhone').value.trim(),tags:$('#contactTags').value.split(',').map(x=>x.trim()).filter(Boolean),optIn:$('#contactOptIn').checked})});$('#crmDialog').close();await loadContacts();toast('Contact added','success')}catch(err){toast(err.message,'error')}})}
function pickContact(){const choices=Object.values(state.contacts).map(c=>`<button class="contact-picker-row" data-pick-jid="${escapeHtml(c.jid)}"><span>${escapeHtml(c.name||'Unknown')}</span><small>${escapeHtml((c.jid||'').replace(/@s\.whatsapp\.net$/,''))}</small></button>`).join('')||'<p>No contacts available.</p>';showDialog(`<div class="dialog-content"><h2>Choose a CRM contact</h2><div class="contact-picker">${choices}</div><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button></div></div>`);document.querySelectorAll('[data-pick-jid]').forEach(btn=>btn.addEventListener('click',()=>{$('#quickRecipient').value=btn.dataset.pickJid.replace(/@s\.whatsapp\.net$/,'');$('#crmDialog').close()}));}
function editActiveContact(){
  const c=state.activeContact||{};
  if(!c.jid)return toast('Open a contact first','error');
  showDialog(`<div class="dialog-content"><h2>Edit CRM profile</h2><p class="muted">The CRM name is an override only. It does not alter the name saved in WhatsApp.</p><label>CRM display name<input id="profileNameInput" value="${escapeHtml(c.name||'')}"></label><label>Email<input id="profileEmail" value="${escapeHtml(c.email||'')}"></label><label>Institution<input id="profileInstitution" value="${escapeHtml(c.institution||'')}"></label><label>Role / title<input id="profileRole" value="${escapeHtml(c.role||'')}"></label><label>Country<input id="profileCountry" value="${escapeHtml(c.country||'')}"></label><label class="checkbox-row"><input id="profileOptIn" type="checkbox" ${c.optIn===true||c.optedIn===true?'checked':''}> Recorded marketing opt-in</label><div class="danger-zone"><b>Remove CRM record</b><p>This removes ScholarVault CRM fields, tags and follow-up data only. It cannot delete this person from WhatsApp Business or your mobile address book.</p><button id="deleteCrmContact" class="danger-btn" type="button">Remove from CRM</button></div><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="saveProfile" class="primary-btn" value="default">Save profile</button></div></div>`);
  $('#deleteCrmContact').addEventListener('click',async()=>{
    const confirmed=confirm(`Remove ${c.name||c.jid} from ScholarVault CRM?\n\nThis will NOT delete the person from WhatsApp Business or your phone contacts.`);
    if(!confirmed)return;
    try{await api(`/api/contacts/${encodeURIComponent(c.jid)}`,{method:'DELETE'});$('#crmDialog').close();state.activeContact={jid:c.jid,name:c.name};updateProfile();await Promise.all([loadContacts(),loadInbox()]);toast('Removed from CRM only. WhatsApp contact was not changed.','success')}catch(err){toast(err.message,'error')}
  });
  $('#saveProfile').addEventListener('click',async e=>{e.preventDefault();try{const update={email:$('#profileEmail').value.trim(),institution:$('#profileInstitution').value.trim(),role:$('#profileRole').value.trim(),country:$('#profileCountry').value.trim(),optIn:$('#profileOptIn').checked};const name=$('#profileNameInput').value.trim();if(name)await api(`/api/contacts/${encodeURIComponent(c.jid)}/identity`,{method:'POST',body:JSON.stringify({name})});await api(`/api/contacts/${encodeURIComponent(c.jid)}/profile`,{method:'POST',body:JSON.stringify(update)});state.activeContact={...state.activeContact,...update,name:name||c.name};$('#crmDialog').close();updateProfile();await loadInbox();toast('CRM profile saved','success')}catch(err){toast(err.message,'error')}})
}
async function reconcileInbox(){try{const preview=await api('/api/inbox/reconcile',{method:'POST',body:JSON.stringify({})});showDialog(`<div class="dialog-content"><h2>Review message sync records</h2><p><b>${preview.beforeCount||0}</b> stored rows currently resolve to <b>${preview.afterCount||0}</b> canonical conversations.</p><p class="muted">Nothing has changed. Applying keeps the newest record for each WhatsApp JID and does not delete conversation history.</p><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="applyReconcile" class="primary-btn" value="default">Apply safe cleanup</button></div></div>`);$('#applyReconcile').addEventListener('click',async e=>{e.preventDefault();await api('/api/inbox/reconcile',{method:'POST',body:JSON.stringify({apply:true})});$('#crmDialog').close();await loadInbox();toast('Duplicate inbox rows reconciled','success')});}catch(e){toast(e.message,'error')}}
function duplicateModal(){api('/api/contacts/duplicates').then(data=>{const groups=data.duplicates||[];showDialog(`<div class="dialog-content"><h2>Duplicate contacts</h2><p>${groups.length?`${groups.length} duplicate group(s) found. Use the established merge logic from the Contacts workspace.`:'No duplicates found.'}</p>${groups.map((g,i)=>`<p><b>Group ${i+1}:</b> ${g.map(c=>escapeHtml(c.name||c.jid)).join(', ')}</p>`).join('')}<div class="dialog-actions"><button class="primary-btn" value="cancel">Close</button></div></div>`)}).catch(e=>toast(e.message,'error'))}
function importContacts(){showDialog(`<div class="dialog-content"><h2>Import contacts</h2><p>CSV columns: phone, name, optional tags. Existing records can be merged without overwriting confirmed names.</p><label class="file-label">Choose CSV<input id="crmImportFile" type="file" accept=".csv,.txt"></label><label>Duplicate handling<select id="crmImportMode"><option value="merge">Merge missing fields</option><option value="ignore">Keep existing records</option><option value="replace">Replace matching records</option></select></label><div id="crmImportPreview" class="csv-preview">Select a file to preview it.</div><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="runImport" class="primary-btn" value="default">Import contacts</button></div></div>`);let imported=[];$('#crmImportFile').addEventListener('change',async e=>{try{imported=await parseCsv(e.target.files[0]);$('#crmImportPreview').textContent=`${imported.length} contacts ready to import.`}catch{toast('Could not read CSV','error')}});$('#runImport').addEventListener('click',async e=>{e.preventDefault();if(!imported.length)return toast('Choose a CSV with contacts','error');const contacts={};imported.forEach(c=>{const jid=`${String(c.phone||'').replace(/\D/g,'')}@s.whatsapp.net`;contacts[jid]={jid,name:c.name||'',tags:c.tags||[]}});try{await api('/api/contacts/bulk',{method:'POST',body:JSON.stringify({contacts,mode:$('#crmImportMode').value})});$('#crmDialog').close();await loadContacts();toast('Contacts imported','success')}catch(err){toast(err.message,'error')}})}

function parseCsv(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n/).filter(Boolean);const start=/phone|number|name/i.test(lines[0]||'')?1:0;resolve(lines.slice(start).map(line=>{const p=line.replace(/"/g,'').split(/[;,\t]/);return {phone:(p[0]||'').replace(/\D/g,''),name:(p[1]||'').trim()}}).filter(x=>x.phone.length>=10));};reader.onerror=reject;reader.readAsText(file)})}
function quickRecipientRows(){return $('#quickRecipient').value.split(/[\s,]+/).map(raw=>raw.trim()).filter(Boolean).map(raw=>{const phone=raw.replace(/\D/g,'');const formatValid=/^[1-9]\d{7,14}$/.test(phone);return {raw,phone,formatValid};});}
function quickRecipientSignature(){return quickRecipientRows().map(row=>row.phone||row.raw).join('|');}
function renderQuickValidation(rows=quickRecipientRows(), verification=null){const target=$('#quickValidation');if(!rows.length){target.textContent='Paste numbers to check their country-code format, then validate WhatsApp availability.';return;}const checked=verification?.byPhone||{};const chips=rows.map(row=>{const result=checked[row.phone];const status=!row.formatValid?'invalid':result===false?'invalid':result===true?'valid':'pending';const note=!row.formatValid?'needs a country-code number':result===false?'not on WhatsApp':result===true?'WhatsApp verified':'format looks valid';return `<span class="recipient-chip ${status}">${escapeHtml(row.raw)} · ${note}</span>`;}).join('');const formatted=rows.filter(row=>row.formatValid).length;const verified=Object.values(checked).filter(value=>value===true).length;const invalid=rows.length-formatted+Object.values(checked).filter(value=>value===false).length;target.innerHTML=`<strong>${rows.length} recipient${rows.length===1?'':'s'}</strong> · ${verification?`${verified} WhatsApp verified, ${invalid} blocked from send.`:`${formatted} ready to validate, ${rows.length-formatted} format issue${rows.length-formatted===1?'':'s'}.`}<div class="recipient-chips">${chips}</div>`;}
async function validateQuickRecipients({silent=false}={}){const rows=quickRecipientRows();renderQuickValidation(rows);const numbers=[...new Set(rows.filter(row=>row.formatValid).map(row=>row.phone))];if(!numbers.length){if(!silent)toast('Add at least one complete country-code number','error');return {valid:[],invalid:rows.map(row=>row.phone||row.raw)};}try{const response=await api('/api/validate-numbers',{method:'POST',body:JSON.stringify({phones:numbers})});const byPhone={};for(const item of response.results||[]){const phone=String(item.number||item.jid||'').replace(/\D/g,'');if(phone)byPhone[phone]=Boolean(item.exists);}for(const phone of response.invalid||[])byPhone[String(phone).replace(/\D/g,'')]=false;const valid=numbers.filter(phone=>byPhone[phone]===true);const invalid=numbers.filter(phone=>byPhone[phone]!==true);state.quickValidation={signature:quickRecipientSignature(),valid,invalid,byPhone};renderQuickValidation(rows,state.quickValidation);if(!silent)toast(`${valid.length} WhatsApp number${valid.length===1?'':'s'} verified${invalid.length?`; ${invalid.length} unavailable`:''}`,invalid.length?'error':'success');return state.quickValidation;}catch(error){renderQuickValidation(rows);if(!silent)toast(`Could not validate numbers: ${error.message}`,'error');throw error;}}
function clearQuickDraft(){
  if($('#quickRecipient')) $('#quickRecipient').value = '';
  if($('#quickText')) $('#quickText').value = '';
  if($('#quickSchedule')) $('#quickSchedule').value = '';
  if($('#quickTemplate')) $('#quickTemplate').value = '';
  if($('#quickTemplatePreview')) $('#quickTemplatePreview').textContent = 'Select a template to preview and insert it.';
  state.quickValidation = null;
  state.quickAttachments = [];
  state.quickPoll = null;
  renderAttachmentChips('quick');
  renderQuickValidation([]);
}
async function loadQuickQueue(){
  const target=$('#quickQueue');
  if(!target)return;
  try{
    const data=await api('/api/campaigns');
    const allQuick=Object.entries(data.campaigns||{}).map(([id,c])=>({id,...c})).filter(c=>String(c.name||'').startsWith('Quick message'));
    const active=allQuick.filter(c=>['scheduled','processing','running','stopped','paused_limit'].includes(String(c.status||'').toLowerCase())).sort((a,b)=>Number(a.scheduledFor||0)-Number(b.scheduledFor||0));
    const recent=allQuick.filter(c=>String(c.status||'').toLowerCase()==='completed').sort((a,b)=>new Date(b.completedAt||b.createdAt||0).getTime()-new Date(a.completedAt||a.createdAt||0).getTime()).slice(0, 4);
    
    const activeRows=active.map(c=>{
      const canStop=['scheduled','processing','running','paused_limit'].includes(String(c.status||'').toLowerCase());
      const isSending=['processing','running'].includes(String(c.status||'').toLowerCase());
      const badge=isSending?'<span style="color:#d98613;font-weight:700">Sending…</span>':escapeHtml(c.status||'scheduled');
      return `<div class="quick-queue-row"><span><b>${badge}</b><small>${escapeHtml(new Date(c.scheduledFor||c.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))} · ${(c.sentCount||0)}/${(c.contacts||[]).length} sent</small></span>${canStop?`<button class="text-btn danger-text" data-stop-campaign="${escapeHtml(c.id)}">Stop</button>`:''}</div>`;
    }).join('');

    const recentRows=recent.map(c=>`
      <div class="quick-queue-row completed-row">
        <span><b class="text-success"><i data-lucide="check-check"></i> Delivered</b><small>${escapeHtml(new Date(c.completedAt||c.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))} · ${(c.sentCount||0)}/${(c.contacts||[]).length} sent</small></span>
      </div>
    `).join('');

    const content=(activeRows || recentRows)?(activeRows + recentRows):'<p class="muted">No recent Quick Messages.</p>';
    target.innerHTML='<h3>Recent & active sends</h3>'+content;
    iconRefresh();
  }catch(error){
    target.innerHTML='<h3>Recent & active sends</h3><p>Queue status is temporarily unavailable.</p>';
  }
}
