// Native CRM modules replace the first-pass iframe bridge. The older
// declaration above is intentionally overridden here to keep the router
// independent from the legacy dashboard.
// The existing inbox endpoint calls its array `messages`; retain `inbox` as
// a compatibility fallback for future backend versions.
function canonicalInbox(records){ const byJid=new Map(); for(const raw of Array.isArray(records)?records:[]){ const jid=String(raw?.jid||'').toLowerCase(); if(!jid||jid.includes('@g.us'))continue; const row={...raw,jid}; const old=byJid.get(jid); const rowTime=new Date(row.lastMessageAt||row.timestamp||0).getTime()||0; const oldTime=new Date(old?.lastMessageAt||old?.timestamp||0).getTime()||0; if(!old||rowTime>=oldTime)byJid.set(jid,row); } return [...byJid.values()].map(row=>{ const contact=state.contacts[row.jid]||{}; return {...row,name:contact.displayNameOverride||contact.name||row.name||row.jid.split('@')[0],profilePictureUrl:contact.profilePictureUrl||row.profilePictureUrl||null,lastMessageAt:row.lastMessageAt||row.timestamp}; }).sort((a,b)=>(new Date(b.lastMessageAt||b.timestamp||0).getTime()||0)-(new Date(a.lastMessageAt||a.timestamp||0).getTime()||0)); }
function unreadConversationCount(){const seen=JSON.parse(localStorage.getItem('scholarvault-crm-inbox-seen')||'{}');return state.inbox.filter(row=>{const lastInbound=new Date(row.lastReceivedAt||0).getTime()||0;return lastInbound>0&&lastInbound>Number(seen[row.jid]||0)}).length}
function initialiseInboxReadBaseline(){if(localStorage.getItem('scholarvault-crm-inbox-read-baseline'))return;const seen={};state.inbox.forEach(row=>{const receivedAt=new Date(row.lastReceivedAt||0).getTime()||0;if(receivedAt)seen[row.jid]=receivedAt});localStorage.setItem('scholarvault-crm-inbox-seen',JSON.stringify(seen));localStorage.setItem('scholarvault-crm-inbox-read-baseline','1')}
function renderInboxBadge(){const badge=$('#inboxCount');const unread=unreadConversationCount();badge.textContent=unread||'';badge.hidden=!unread;badge.title=unread?`${unread} chat${unread===1?'':'s'} need your attention`:''}
function markConversationRead(jid){const row=state.inbox.find(item=>item.jid===jid);const receivedAt=new Date(row?.lastReceivedAt||0).getTime()||0;if(!receivedAt)return;const seen=JSON.parse(localStorage.getItem('scholarvault-crm-inbox-seen')||'{}');if(Number(seen[jid]||0)>=receivedAt)return;seen[jid]=receivedAt;localStorage.setItem('scholarvault-crm-inbox-seen',JSON.stringify(seen));renderInboxBadge()}
async function loadInbox(){ try { const data=await api('/api/inbox'); state.inbox=canonicalInbox(data.messages||data.inbox||[]); initialiseInboxReadBaseline(); renderInboxBadge(); $('#conversationSubtitle').textContent=`${state.inbox.length} conversations`; renderChatList(); if(state.activeJid)await openChat(state.activeJid,false); }catch(e){$('#chatList').innerHTML=`<p class="drawer-empty">Could not load inbox: ${escapeHtml(e.message)}</p>`;} }
