async function loadOverview(){try{const [inboxData,contactsData,campaignsData,leadsData,pipelineData,health]=await Promise.all([api('/api/inbox'),api('/api/contacts'),api('/api/campaigns'),api('/api/hot-leads'),api('/api/pipeline').catch(()=>({pipeline:{}})),api('/api/health').catch(()=>({state:'offline'}))]);const inbox=canonicalInbox(inboxData.messages||inboxData.inbox||[]);const contacts=Object.values(contactsData.contacts||{});const campaigns=Object.entries(campaignsData.campaigns||{}).map(([id,c])=>({id,...c})).sort((a,b)=>new Date(b.createdAt||b.scheduledFor||0)-new Date(a.createdAt||a.scheduledFor||0));const leads=leadsData.leads||[];const upcoming=campaigns.filter(c=>['scheduled','running','processing','active'].includes(String(c.status||'').toLowerCase()));$('#metricGrid').innerHTML=[['Active conversations',inbox.length,'Live WhatsApp inbox'],['CRM contacts',contacts.length,'Audience ready'],['Campaigns',campaigns.length,upcoming.length?`${upcoming.length} active or scheduled`:`${campaigns.filter(c=>c.status==='completed').length} completed`],['Hot leads',leads.length,'Priority follow-up']].map(([l,n,s])=>`<div class="metric-card"><span class="metric-label">${l}</span><strong>${n}</strong><small>${s}</small></div>`).join('');const attention=[...leads.slice(0,3).map(lead=>({kind:'hot',jid:lead.jid||lead.phone?`${String(lead.jid||lead.phone).replace(/@.*$/,'')}@s.whatsapp.net`:null,name:lead.name||lead.phone||'Hot lead',detail:lead.message||lead.keyword||'Priority follow-up',time:lead.timestamp})),...inbox.filter(c=>c.escalated).slice(0,2).map(c=>({kind:'warn',jid:c.jid,name:c.name||c.jid,detail:'Human takeover is active',time:c.timestamp})),...inbox.filter(c=>!c.escalated).slice(0,3).map(c=>({kind:'chat',jid:c.jid,name:c.name||c.jid,detail:c.message||'New conversation activity',time:c.lastMessageAt||c.timestamp}))].slice(0,6);$('#attentionList').innerHTML=attention.map(item=>`<button class="attention-row" ${item.jid?`data-open-chat="${escapeHtml(item.jid)}"`:''}><span class="attention-icon ${item.kind==='hot'?'hot':item.kind==='warn'?'warn':''}"><i data-lucide="${item.kind==='hot'?'flame':item.kind==='warn'?'shield-alert':'message-circle'}"></i></span><span><b>${escapeHtml(item.name)}</b><span>${escapeHtml(item.detail)}</span></span><time>${formatTime(item.time)}</time></button>`).join('')||'<p class="muted">No priority work right now.</p>';const isOnline=String(health.state||'').toLowerCase()==='open';const operations=[{state:isOnline?'online':'muted',title:isOnline?'WhatsApp connected':'WhatsApp connection needs attention',detail:isOnline?'Live inbound and outbound sync is ready.':'Open WhatsApp instances to reconnect Evolution.'},{state:state.masterPaused?'paused':'online',title:state.masterPaused?'Master AI is paused':'Master AI is active',detail:state.masterPaused?'Automated responses are blocked; manual work remains available.':'Automation follows your Mistral and guardrail rules.'},...upcoming.slice(0,2).map(c=>({state:'online',title:c.name||'Scheduled campaign',detail:`${c.contacts?.length||0} contacts · ${c.scheduledFor?new Date(c.scheduledFor).toLocaleString():'Running now'}`}))];$('#operationsList').innerHTML=operations.map(item=>`<div class="operation-row"><i class="operation-state ${item.state==='paused'?'paused':item.state==='muted'?'muted':''}"></i><span><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.detail)}</span></span></div>`).join('');$('#overviewCampaigns').innerHTML=`<table><thead><tr><th>Campaign</th><th>Status</th><th>Audience</th><th>Sent</th><th>Failed</th></tr></thead><tbody>${campaigns.slice(0,5).map(c=>{const status=String(c.status||'scheduled');return `<tr><td><b>${escapeHtml(c.name||c.id)}</b><br><small>${escapeHtml(c.scheduledFor?new Date(c.scheduledFor).toLocaleString():'Created '+new Date(c.createdAt||Date.now()).toLocaleDateString())}</small></td><td><span class="status-chip ${status.toLowerCase()==='completed'?'completed':status.toLowerCase()==='failed'?'failed':''}">${escapeHtml(status)}</span></td><td>${c.contacts?.length||c.totalCount||0}</td><td>${c.sentCount||0}</td><td>${c.failedCount||0}</td></tr>`}).join('')||'<tr><td colspan="5">No campaigns created yet. Use Bulk campaigns to begin.</td></tr>'}</tbody></table>`;const stages=['New','Messaged','Replied','Interested','Registered','Attended'];const grouped=pipelineData.pipeline&&typeof pipelineData.pipeline==='object'?pipelineData.pipeline:{};const total=Math.max(1,stages.reduce((sum,stage)=>sum+(grouped[stage]||[]).length,0));$('#overviewPipeline').innerHTML=stages.map(stage=>{const count=(grouped[stage]||[]).length;return `<div class="pipeline-meter"><b>${stage}</b><span class="pipeline-track"><i style="width:${Math.round(count/total*100)}%"></i></span><span>${count}</span></div>`}).join('');iconRefresh()}catch(e){$('#metricGrid').innerHTML=`<div class="metric-card" style="grid-column:1/-1">Could not load dashboard data: ${escapeHtml(e.message)}</div>`;}}
// Overview attention is reconciled against the canonical inbox after every render.
