// Inbox send review: choosing a file never dispatches it. The operator must
// confirm the caption and click Send in the preview dialog.
async function sendAttachment(file, context='chat'){
  if(!file)return;
  try{
    const media=await readFile(file);
    if(context!=='chat'){
      state[context==='campaign'?'campaignAttachments':'quickAttachments'].push({base64:media,name:file.name});
      renderAttachmentChips(context); return;
    }
    if(!state.activeJid)throw new Error('Select a conversation first');
    const isImage=String(file.type||'').startsWith('image/');
    const preview=isImage?`<img class="attachment-preview" src="${escapeHtml(media)}" alt="${escapeHtml(file.name)}">`:`<div class="attachment-file-preview"><i data-lucide="file-text"></i><b>${escapeHtml(file.name)}</b><small>${escapeHtml(file.type||'Document')}</small></div>`;
    showDialog(`<div class="dialog-content send-review"><h2>Send attachment</h2>${preview}<label>Caption (optional)<textarea id="attachmentCaption" rows="4" placeholder="Add a message with this attachment">${escapeHtml($('#messageInput').value.trim())}</textarea></label><p class="muted">Nothing is sent until you click Send attachment.</p><div class="dialog-actions"><button class="secondary-btn" value="cancel">Cancel</button><button id="confirmAttachmentSend" class="primary-btn" value="default">Send attachment</button></div></div>`);
    $('#confirmAttachmentSend').addEventListener('click',async event=>{event.preventDefault();const button=$('#confirmAttachmentSend');button.disabled=true;button.textContent='Sending…';try{await api(`/api/inbox/${encodeURIComponent(state.activeJid)}/media`,{method:'POST',body:JSON.stringify({media,mediatype:isImage?'image':String(file.type||'').startsWith('video/')?'video':String(file.type||'').startsWith('audio/')?'audio':'document',fileName:file.name,caption:$('#attachmentCaption').value.trim()})});$('#messageInput').value='';$('#crmDialog').close();await openChat(state.activeJid,false);toast('Attachment sent','success')}catch(error){button.disabled=false;button.textContent='Send attachment';toast(error.message,'error')}});
  }catch(error){toast(error.message,'error')}
}
function showAllMedia(){
  const items=(state.activeThread||[]).filter(item=>item.mediaUrl);
  if(!items.length)return toast('No media or files are stored for this conversation yet.','error');
  const content=items.map(item=>{const type=String(item.mediaType||item.messageType||'').toLowerCase();const url=escapeHtml(item.mediaUrl);if(type.includes('image'))return `<a class="media-viewer-item" href="${url}" target="_blank"><img src="${url}" alt="${escapeHtml(item.fileName||'Image')}"><span>${escapeHtml(item.fileName||'Image')}</span></a>`;if(type.includes('video'))return `<a class="media-viewer-item" href="${url}" target="_blank"><i data-lucide="video"></i><span>${escapeHtml(item.fileName||'Video')}</span></a>`;if(type.includes('audio'))return `<div class="media-viewer-item"><audio controls src="${url}"></audio><span>Voice note</span></div>`;return `<a class="media-viewer-item" href="${url}" target="_blank"><i data-lucide="file-text"></i><span>${escapeHtml(item.fileName||'Document')}</span></a>`;}).join('');
  showDialog(`<div class="dialog-content media-viewer"><h2>Media & files</h2><div class="media-viewer-grid">${content}</div><div class="dialog-actions"><button class="primary-btn" value="cancel">Close</button></div></div>`);
}
async function recordVoice(){
  if(!state.activeJid)return toast('Select a conversation first','error');
  if(state.recorder?.state==='recording'){state.recorder.stop();return;}
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true});state.chunks=[];state.recorder=new MediaRecorder(stream);
    state.recorder.ondataavailable=event=>state.chunks.push(event.data);
    state.recorder.onstop=async()=>{stream.getTracks().forEach(track=>track.stop());$('#voiceButton').classList.remove('recording');try{const blob=new Blob(state.chunks,{type:'audio/webm'});const base64=await readFile(blob);const previewUrl=URL.createObjectURL(blob);showDialog(`<div class="dialog-content voice-review"><h2>Review voice note</h2><audio controls autoplay src="${previewUrl}"></audio><p class="muted">Listen before sending. Discard leaves the chat unchanged.</p><div class="dialog-actions"><button id="discardVoice" class="secondary-btn" value="cancel">Discard</button><button id="sendVoice" class="primary-btn" value="default">Send voice note</button></div></div>`);$('#sendVoice').addEventListener('click',async event=>{event.preventDefault();const button=$('#sendVoice');button.disabled=true;button.textContent='Sending…';try{await api('/api/chat/send-audio',{method:'POST',body:JSON.stringify({jid:state.activeJid,base64})});URL.revokeObjectURL(previewUrl);$('#crmDialog').close();await openChat(state.activeJid,false);toast('Voice note sent','success')}catch(error){button.disabled=false;button.textContent='Send voice note';toast(error.message,'error')}});$('#discardVoice').addEventListener('click',()=>URL.revokeObjectURL(previewUrl));}catch(error){toast(error.message,'error')}};
    state.recorder.start();$('#voiceButton').classList.add('recording');toast('Recording… click the microphone again to stop and review.');
  }catch(error){toast('Microphone access is required to record a voice note','error')}
}
