function closeMessageMenu(){document.querySelector('.context-menu')?.remove()}
async function reactToMessage(id,reaction){if(!id||!state.activeJid)return;try{await api('/message/sendReaction/ScholarVault',{method:'POST',body:JSON.stringify({jid:state.activeJid,messageId:id,reaction,fromMe:Boolean(state.activeThread.find(m=>(m.id||m.messageId)===id)?.fromMe)})});await openChat(state.activeJid,false)}catch(e){toast(e.message,'error')}}
document.addEventListener('contextmenu',e=>{const bubble=e.target.closest('.bubble');if(!bubble)return;const id=bubble.querySelector('[data-message-id]')?.dataset.messageId;if(!id)return;e.preventDefault();closeMessageMenu();const row=state.activeThread.find(m=>(m.id||m.messageId)===id)||{};const mine=Boolean(row.fromMe||row.direction==='out');const menu=document.createElement('div');menu.className='context-menu';menu.style.left=`${e.clientX}px`;menu.style.top=`${e.clientY}px`;menu.innerHTML=`<div class="reaction-strip">${['👍','❤️','😂','😮','😢','🙏'].map(x=>`<button data-react="${x}">${x}</button>`).join('')}</div><button data-menu="copy">Copy</button>${mine?'<button data-menu="edit">Edit</button>':''}<button data-menu="me">Delete for me</button>${mine?'<button class="danger" data-menu="everyone">Delete for everyone</button>':''}`;document.body.append(menu);menu.onclick=async x=>{const reaction=x.target.closest('[data-react]')?.dataset.react;const action=x.target.closest('[data-menu]')?.dataset.menu;if(reaction)await reactToMessage(id,reaction);if(action==='copy')navigator.clipboard?.writeText(row.text||'');if(action==='edit')messageAction('edit',id);if(action==='me'||action==='everyone')messageAction(action,id);closeMessageMenu()};});document.addEventListener('click',e=>{if(!e.target.closest('.context-menu'))closeMessageMenu()});
